// Polyfill wrapper — see lib/pdfjs.ts's installMapPolyfills() doc comment
// for why this is needed. A Worker has its own global scope, separate from
// the main thread's, so the main-thread polyfill there doesn't reach here —
// this file must install its own copy before pdf.worker.real.js (the real,
// unmodified pdfjs-dist worker build) runs.
if (typeof Map.prototype.getOrInsertComputed !== "function") {
  Map.prototype.getOrInsertComputed = function (key, callback) {
    if (this.has(key)) return this.get(key);
    const value = callback(key);
    this.set(key, value);
    return value;
  };
}
if (typeof Map.prototype.getOrInsert !== "function") {
  Map.prototype.getOrInsert = function (key, value) {
    if (this.has(key)) return this.get(key);
    this.set(key, value);
    return value;
  };
}

import "./pdf.worker.real.js";
